//! Review-only checks for fixtures generated by scripts/adr024-fixtures.py.
//! Run explicitly with ADR024_FIXTURES pointing to a disposable fixture directory.
#![cfg(unix)]
use serapendiya::{domain::Offset, storage::Log};
use std::{collections::BTreeMap, fs, path::Path};

fn snapshot(dir: &Path) -> BTreeMap<String, (Vec<u8>, u64, u32)> {
    use std::os::unix::fs::MetadataExt;
    fs::read_dir(dir)
        .unwrap()
        .map(|e| {
            let e = e.unwrap();
            let m = e.metadata().unwrap();
            (
                e.file_name().into_string().unwrap(),
                (fs::read(e.path()).unwrap(), m.ino(), m.mode()),
            )
        })
        .collect()
}

// Review verifier deliberately parses bytes independently of the Python writer.
fn verify_manifest(bytes: &[u8]) -> bool {
    if bytes.len() < 76 || &bytes[..4] != b"SRSM" || bytes[4..8] != [1, 0, 0, 0] {
        return false;
    }
    let n = u32::from_be_bytes(bytes[12..16].try_into().unwrap()) as usize;
    if !(1..=4096).contains(&n)
        || bytes.len() != 52 + 24 * n
        || u32::from_be_bytes(bytes[8..12].try_into().unwrap()) as usize != bytes.len()
        || bytes[16..32].iter().all(|b| *b == 0)
    {
        return false;
    }
    let end = bytes.len() - 4;
    if crc32c::crc32c(&bytes[..end]) != u32::from_be_bytes(bytes[end..].try_into().unwrap()) {
        return false;
    }
    let mut next = 0;
    for (i, entry) in bytes[48..end].chunks_exact(24).enumerate() {
        let base = u64::from_be_bytes(entry[..8].try_into().unwrap());
        let last = u64::from_be_bytes(entry[8..16].try_into().unwrap());
        let len = u64::from_be_bytes(entry[16..].try_into().unwrap());
        if base != next
            || last < base
            || (i + 1 < n && (last == base || len == 0))
            || (last == base) != (len == 0)
        {
            return false;
        }
        next = last;
    }
    next <= i64::MAX as u64 + 1 && next == u64::from_be_bytes(bytes[32..40].try_into().unwrap())
}

fn verify_frame(bytes: &[u8], offset: u64, payload: &[u8]) -> bool {
    if bytes.len() < 99 || &bytes[..8] != b"SRB1\x01\0\0\0" {
        return false;
    }
    let u32at = |p| u32::from_be_bytes(bytes[p..p + 4].try_into().unwrap());
    let u64at = |p| u64::from_be_bytes(bytes[p..p + 8].try_into().unwrap());
    let batch = &bytes[32..];
    if u32at(8) as usize != batch.len()
        || u64at(12) != offset
        || u32at(20) != 1
        || u32at(28) != crc32c::crc32c(&bytes[..28])
        || u32at(24) != crc32c::crc32c(batch)
        || u64at(32) != offset
        || u32at(40) as usize + 12 != batch.len()
        || batch[16] != 2
        || u32at(49) != crc32c::crc32c(&batch[21..])
    {
        return false;
    }
    // These golden records use one-byte varints and a single unkeyed record.
    let record = &batch[61..];
    record.len() == payload.len() + 7
        && record[0] as usize == 2 * (payload.len() + 6)
        && record[1..5] == [0, 0, 0, 1]
        && record[5] as usize == 2 * payload.len()
        && &record[6..record.len() - 1] == payload
        && record[record.len() - 1] == 0
}

#[test]
#[ignore = "requires explicitly generated disposable review fixtures"]
fn legacy_frames_and_new_layout_refusal() {
    let root = std::path::PathBuf::from(std::env::var_os("ADR024_FIXTURES").unwrap());
    let mut old = Log::open(root.join("legacy-source")).unwrap();
    for (offset, expected) in [b"alpha".as_slice(), b"beta".as_slice()].iter().enumerate() {
        assert_eq!(
            old.read_batch(Offset::new(offset as u64))
                .unwrap()
                .unwrap()
                .records,
            *expected
        );
    }
    drop(old);
    for name in ["empty", "two", "migrated", "nonunit-base"] {
        assert!(verify_manifest(
            &fs::read(root.join(name).join("manifest")).unwrap()
        ));
    }
    for name in [
        "bad-checksum",
        "future-version",
        "offset-gap",
        "reserved-byte",
        "duplicate-entry",
        "bad-length",
        "truncated-manifest",
        "zero-identity",
    ] {
        assert!(!verify_manifest(
            &fs::read(root.join(name).join("manifest")).unwrap()
        ));
    }
    for name in ["two", "migrated", "corrupt-payload"] {
        let manifest = fs::read(root.join(name).join("manifest")).unwrap();
        for (i, payload) in [b"alpha".as_slice(), b"beta".as_slice()].iter().enumerate() {
            let start = 48 + 24 * i;
            let base = u64::from_be_bytes(manifest[start..start + 8].try_into().unwrap());
            let frame = fs::read(root.join(name).join(format!("segment-{base:020}.log"))).unwrap();
            assert_eq!(
                u64::from_be_bytes(manifest[64 + 24 * i..72 + 24 * i].try_into().unwrap()),
                frame.len() as u64
            );
            assert_eq!(
                verify_frame(&frame, base, payload),
                name != "corrupt-payload" || i != 0
            );
        }
    }
    let name = "nonunit-base";
    let manifest = fs::read(root.join(name).join("manifest")).unwrap();
    for i in 0..2 {
        let start = 48 + 24 * i;
        let base = u64::from_be_bytes(manifest[start..start + 8].try_into().unwrap());
        let end = u64::from_be_bytes(manifest[start + 8..start + 16].try_into().unwrap());
        let segment = fs::read(root.join(name).join(format!("segment-{base:020}.log"))).unwrap();
        assert_eq!(
            u64::from_be_bytes(manifest[start + 16..start + 24].try_into().unwrap()),
            segment.len() as u64
        );
        let mut pos = 0;
        for offset in base..end {
            let len =
                u32::from_be_bytes(segment[pos + 8..pos + 12].try_into().unwrap()) as usize + 32;
            let value = if offset == 5 {
                b"beta".as_slice()
            } else {
                b"alpha".as_slice()
            };
            assert!(verify_frame(&segment[pos..pos + len], offset, value));
            pos += len;
        }
        assert_eq!(pos, segment.len());
    }
    for name in [
        "empty",
        "nonunit-base",
        "two",
        "migrated",
        "bad-checksum",
        "future-version",
        "offset-gap",
        "reserved-byte",
        "corrupt-payload",
        "duplicate-entry",
        "bad-length",
        "truncated-manifest",
        "zero-identity",
    ] {
        let dir = root.join(name);
        let before = snapshot(&dir);
        for _ in 0..2 {
            assert!(Log::open(&dir).is_err(), "old reader accepted {name}");
            assert_eq!(snapshot(&dir), before, "old reader modified {name}");
        }
    }
}
